pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };

    let pressure = (open_bins_count as f64).sqrt() / (1.0 + progress);
    score += pressure;

    let dead_threshold = (item_size as f64 * 0.35).max(8.0);
    if (post_residual as f64) < dead_threshold {
        let severity = (dead_threshold - post_residual as f64) / dead_threshold;
        score += severity * 18.0 * (1.0 - progress);
    }

    if post_residual < next_item_size && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    let capacity = bin_capacity.max(1) as f64;
    let residual = bin_residual as f64;
    let utilization = (capacity - residual) / capacity;
    score += (1.0 - utilization) * 5.0;

    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    if post_residual == 0 {
        score -= 20.0;
    }

    score -= (mean_residual - post_residual as f64).abs() * 0.25;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        1.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Small residual gaps are especially difficult to reuse, so penalize them
    // sharply when the current item is large relative to the remaining gap.
    let item = item_size as f64;
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let lookahead = next_item_size as f64;

    let dead_space = if residual <= 0.0 {
        0.0
    } else if residual < item {
        residual
    } else {
        residual * 0.35
    };

    score += dead_space * 1.8;

    // Avoid creating a gap that is too small for the next known item.
    if lookahead > 0.0 && residual > 0.0 && residual < lookahead {
        score += (lookahead - residual) * 2.4;
    }

    // Prefer a tight fit when several bins can accept the item.
    let tightness = if capacity > 0.0 {
        (item / (bin_residual as f64).max(1.0)).min(2.0)
    } else {
        0.0
    };
    score -= tightness * 6.0;

    // If this is the only fitting bin, preserving reusable space is less
    // important than avoiding the imminent opening of another bin.
    if fitting_bins_count <= 1 {
        score -= (open_bins_count as f64).sqrt() * 1.2;
    } else {
        score += (open_bins_count as f64) * 0.08;
    }

    // New bins are attractive only when existing bins are substantially less
    // suitable; their zero post-residual is offset by an opening penalty.
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 0.6;
        score -= progress * 2.0;
    }

    // Gentle pressure toward consolidating items as the stream progresses.
    score -= progress * 0.8;

    // Keep a mild preference for bins near the stream's average residual.
    score += (mean_residual - residual).abs() * 0.025;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let unusable = if post_residual < next_item_size && next_item_size > 0 {
        (next_item_size - post_residual) as f64
    } else if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64
    } else {
        0.0
    };
    score += unusable * 4.0;

    if post_residual == 0 {
        score -= 18.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    let density = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= density * 8.0;

    if bin_residual == bin_capacity {
        score += 12.0;
        if open_bins_count > 0 {
            score += open_bins_count as f64 * 1.5;
        }
    } else if fitting_bins_count == 1 {
        score -= 14.0;
    } else {
        score -= (open_bins_count as f64).min(8.0) * 0.6;
    }

    if next_item_size > 0 {
        let exact_fit = (post_residual == next_item_size) as i32 as f64;
        score -= exact_fit * 8.0;
        if post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    score -= progress * 2.0;

    if mean_residual < item_size as f64 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        score = 0.0;
    } else {
        let dead_space = if post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
            post_residual as f64
        } else {
            0.0
        };
        score += dead_space * 3.0;

        let fragmentation = (post_residual as f64 / bin_capacity as f64).powi(2) * 12.0;
        score += fragmentation;

        if post_residual == 0 {
            score -= 8.0;
        } else if post_residual < item_size {
            score -= 4.0;
        }

        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        let pressure = open_bins_count as f64;
        score += pressure * 0.35;
        score += (mean_residual - post_residual as f64) * 0.08;

        if next_item_size == 0 {
            score -= post_residual as f64 * 0.05;
        }

        if progress > 0.75 {
            score -= (bin_capacity - item_size) as f64 * 0.015;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    let is_new_bin = bin_residual == bin_capacity;
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    let next_mismatch = if next_item_size == 0 {
