    };

    let residual_gap = (post_residual as f64 - mean_residual).abs();
    let scarcity_bonus = if fitting_bins_count <= 1 { 18.0 } else { 0.0 };
    let concentration_penalty = if open_bins_count > 1 {
        (post_residual as f64 / bin_capacity as f64) * 6.0 * (1.0 - progress)
    } else {
        0.0
    };

    score += next_mismatch * 1.35;
    score += residual_gap * 0.28;
    score += concentration_penalty;

    if next_item_size > 0 && next_fits {
        score -= (next_item_size as f64).min(post_residual as f64) * 0.22;
    }

    if next_item_size == 0 {
        score -= post_residual as f64 * 0.08;
